// PlansServiceServer is the server API for PlansService service.
// All implementations must embed UnimplementedPlansServiceServer
// for forward compatibility.
//
// PlansService is the tenant-facing control plane. Every call carries the tenant in metadata (set by the gateway).
type PlansServiceServer interface {
	CreateCustomer(context.Context, *CreateCustomerRequest) (*CreateCustomerResponse, error)
	// GetCustomer looks a customer up by external_id.
	GetCustomer(context.Context, *GetCustomerRequest) (*GetCustomerResponse, error)
	// ResolveCustomer is the internal hot-path lookup (external_id → internal id). Callers cache it.
	ResolveCustomer(context.Context, *ResolveCustomerRequest) (*ResolveCustomerResponse, error)
	ListCustomers(context.Context, *ListCustomersRequest) (*ListCustomersResponse, error)
	// SetPaymentMethod sets the PSP token. Sandbox tenants accept only pm_sandbox_* tokens.
	SetPaymentMethod(context.Context, *SetPaymentMethodRequest) (*SetPaymentMethodResponse, error)
	// CreateMeter creates version 1 of a code, or the next version of an existing code.
	CreateMeter(context.Context, *CreateMeterRequest) (*CreateMeterResponse, error)
	// GetMeter returns the latest version of a code.
	GetMeter(context.Context, *GetMeterRequest) (*GetMeterResponse, error)
	ListMeters(context.Context, *ListMetersRequest) (*ListMetersResponse, error)
	CreatePlan(context.Context, *CreatePlanRequest) (*CreatePlanResponse, error)
	ListPlans(context.Context, *ListPlansRequest) (*ListPlansResponse, error)
	// PublishPlanVersion appends an immutable version.
	PublishPlanVersion(context.Context, *PublishPlanVersionRequest) (*PublishPlanVersionResponse, error)
	GetPlanVersion(context.Context, *GetPlanVersionRequest) (*GetPlanVersionResponse, error)
	CreateSubscription(context.Context, *CreateSubscriptionRequest) (*CreateSubscriptionResponse, error)
	CancelSubscription(context.Context, *CancelSubscriptionRequest) (*CancelSubscriptionResponse, error)
	GetSubscription(context.Context, *GetSubscriptionRequest) (*GetSubscriptionResponse, error)
	// ListSubscriptions pages through subscriptions, newest first, of one customer or all.
	ListSubscriptions(context.Context, *ListSubscriptionsRequest) (*ListSubscriptionsResponse, error)
	// GetRoutingRules returns the ordered rules that choose a customer's payment provider from country and currency.
	GetRoutingRules(context.Context, *GetRoutingRulesRequest) (*GetRoutingRulesResponse, error)
	// SetRoutingRules replaces the rules. Existing subscriptions keep the provider they were created with.
	SetRoutingRules(context.Context, *SetRoutingRulesRequest) (*SetRoutingRulesResponse, error)
	// PreviewRouting says where a customer in a country paying in a currency would go, without creating anything.
	PreviewRouting(context.Context, *PreviewRoutingRequest) (*PreviewRoutingResponse, error)
	// StartProviderMigration moves a subscription to another payment provider without charging the customer twice. The old subscription ends
	// only when the new one takes over (CompleteProviderMigration), or at the cutover time given.
	StartProviderMigration(context.Context, *StartProviderMigrationRequest) (*StartProviderMigrationResponse, error)
	// CompleteProviderMigration is the target provider's confirmation that the customer subscribed there: the cutover happens now.
	CompleteProviderMigration(context.Context, *CompleteProviderMigrationRequest) (*CompleteProviderMigrationResponse, error)
	AbortProviderMigration(context.Context, *AbortProviderMigrationRequest) (*AbortProviderMigrationResponse, error)
	GetProviderMigration(context.Context, *GetProviderMigrationRequest) (*GetProviderMigrationResponse, error)
	// GetSubscriptionReport counts the tenant's subscriptions and their monthly recurring revenue at the end of a month, with the new and the churned of that month,
	// by payment provider, customer country and currency. Currencies are never added together.
	GetSubscriptionReport(context.Context, *GetSubscriptionReportRequest) (*GetSubscriptionReportResponse, error)
	// SyncProviderSubscription records what a payment provider says about a subscription it runs: links it to ours and follows its status.
	// Internal: called by payments-worker, not exposed by the gateway.
	SyncProviderSubscription(context.Context, *SyncProviderSubscriptionRequest) (*SyncProviderSubscriptionResponse, error)
	// PauseSubscription stops the fixed fee from the call until ResumeSubscription. Usage is still metered and billed.
	PauseSubscription(context.Context, *PauseSubscriptionRequest) (*PauseSubscriptionResponse, error)
	ResumeSubscription(context.Context, *ResumeSubscriptionRequest) (*ResumeSubscriptionResponse, error)
	// ScheduleCancellation ends the subscription at the end of its current billing period.
	ScheduleCancellation(context.Context, *ScheduleCancellationRequest) (*ScheduleCancellationResponse, error)
	// ChangePlan ends the subscription and starts a new one on another plan version. The fixed fee of the month is split
	// between the two plans in proportion to the time on each.
	ChangePlan(context.Context, *ChangePlanRequest) (*ChangePlanResponse, error)
	// ListSubscriptionsForPeriod streams subscriptions overlapping [period_start, period_end). Used by billing-svc.
	// ListSubscriptionsFeeDue lists advance-billed subscriptions whose next fee period has started, with the period and the fee. Used by billing-svc.
	// PreviewSubscriptionChange prices a change of plan or interval without making it. ChangeSubscription makes it with the same calculation.
	PreviewSubscriptionChange(context.Context, *PreviewSubscriptionChangeRequest) (*PreviewSubscriptionChangeResponse, error)
	ChangeSubscription(context.Context, *ChangeSubscriptionRequest) (*ChangeSubscriptionResponse, error)
	CancelScheduledChange(context.Context, *CancelScheduledChangeRequest) (*CancelScheduledChangeResponse, error)
	// ApplyScheduledChanges applies the changes whose effective time has come. Used by billing-svc's tick.
	ApplyScheduledChanges(context.Context, *ApplyScheduledChangesRequest) (*ApplyScheduledChangesResponse, error)
	// ListSubscriptionAdjustments lists the money changes moved that billing-svc has not yet invoiced or credited.
	ListSubscriptionAdjustments(context.Context, *ListSubscriptionAdjustmentsRequest) (*ListSubscriptionAdjustmentsResponse, error)
	MarkSubscriptionAdjustmentBilled(context.Context, *MarkSubscriptionAdjustmentBilledRequest) (*MarkSubscriptionAdjustmentBilledResponse, error)
	// GetTaxRates and SetTaxRates hold the tax Quotify adds to the invoices it raises, by customer country. The list is replaced as a whole.
	GetTaxRates(context.Context, *GetTaxRatesRequest) (*GetTaxRatesResponse, error)
	SetTaxRates(context.Context, *SetTaxRatesRequest) (*SetTaxRatesResponse, error)
	CreateCoupon(context.Context, *CreateCouponRequest) (*CreateCouponResponse, error)
	ListCoupons(context.Context, *ListCouponsRequest) (*ListCouponsResponse, error)
	// DeactivateCoupon stops new redemptions; subscriptions that redeemed it keep it.
	DeactivateCoupon(context.Context, *DeactivateCouponRequest) (*DeactivateCouponResponse, error)
	// ApplyCoupon redeems a coupon on a subscription that has none; RemoveCoupon takes it off (the redemption count is not given back).
	ApplyCoupon(context.Context, *ApplyCouponRequest) (*ApplyCouponResponse, error)
	RemoveCoupon(context.Context, *RemoveCouponRequest) (*RemoveCouponResponse, error)
	ListSubscriptionsFeeDue(context.Context, *ListSubscriptionsFeeDueRequest) (*ListSubscriptionsFeeDueResponse, error)
	// AdvanceSubscriptionFee records that the fee period starting at period_start has been dealt with (invoiced or waived). Idempotent.
	AdvanceSubscriptionFee(context.Context, *AdvanceSubscriptionFeeRequest) (*AdvanceSubscriptionFeeResponse, error)
	ListSubscriptionsForPeriod(*ListSubscriptionsForPeriodRequest, grpc.ServerStreamingServer[ListSubscriptionsForPeriodResponse]) error
	mustEmbedUnimplementedPlansServiceServer()
}

